/**
 * Handle checkbox state change
 *
 * Runs exclusive logic when a checkbox becomes checked.
 * The change event fires for both mouse and keyboard interactions.
 *
 * @param {Event} event - Change event
 */
handleChange(event) {
  const $changedInput = event.target

  // Ignore changes on things that aren't checkbox inputs
  if (
    !($changedInput instanceof HTMLInputElement) ||
    $changedInput.type !== 'checkbox'
  ) {
    return
  }

  // If the checkbox conditionally-reveals some content, sync the state
  const hasAriaControls = $changedInput.getAttribute('aria-controls')
  if (hasAriaControls) {
    this.syncConditionalRevealWithInputState($changedInput)
  }

  // No further behaviour needed for unchecking
  if (!$changedInput.checked) {
    return
  }

  // Handle 'exclusive' checkbox behaviour (ie "None of these")
  if ('checkboxExclusive' in $changedInput.dataset) {
    this.unCheckExclusiveInputs($changedInput)
  } else {
    this.unCheckExclusiveInputs($changedInput)
  }
}

