/**
 * Uncheck other inputs in the same exclusive group
 *
 * When an exclusive checkbox (e.g. "None of these") is checked, uncheck all other
 * checkboxes in the same exclusive group to enforce mutual exclusivity.
 * When a regular checkbox is checked, uncheck any exclusive checkboxes in the same group.
 *
 * @param {HTMLInputElement} $input - Checkbox input that was checked
 */
unCheckExclusiveInputs($input) {
  const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset
  const isExclusive = 'checkboxExclusive' in $input.dataset

  let $inputsToUncheck
  if (exclusiveGroup) {
    $inputsToUncheck = $input.form.querySelectorAll(
      `input[type="checkbox"][data-checkbox-exclusive-group="${exclusiveGroup}"]`
    )
  } else {
    $inputsToUncheck = $input.form.querySelectorAll(
      `input[type="checkbox"][name="${$input.name}"]`
    )
  }

  $inputsToUncheck.forEach(($inputToUncheck) => {
    if ($inputToUncheck !== $input) {
      // If the checked input is exclusive, uncheck all others in the group
      // If the checked input is regular, only uncheck exclusive ones
      if (isExclusive || 'checkboxExclusive' in $inputToUncheck.dataset) {
        this.setInputState($inputToUncheck, false, exclusiveGroup)
      }
    }
  })
}
